import fs from 'node:fs';
const root=new URL('../',import.meta.url),all=JSON.parse(fs.readFileSync(new URL('docs/releases.json',root),'utf8'));
const seen=new Set();for(const r of all){if(seen.has(r.id)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!r.title||typeof r.published!=='boolean')throw Error('패치 이력 ID·날짜·상태를 확인하세요.');seen.add(r.id);}
const releases=all.filter(r=>r.published);if(!releases.length)throw Error('공개 이력이 없습니다.');
const outputs={
  'dist/release-notes.js':'// Generated by tools/build-release-notes.mjs. Only published releases.\nexport const RELEASES = '+JSON.stringify(releases,null,2)+';\nexport const RELEASE = RELEASES[0].id;\n',
  'CHANGELOG.md':'# 업데이트 내역\n\n'+releases.map(r=>'## '+r.date+' · '+r.title+'\n\n'+Object.entries(r.changes).map(([kind,items])=>'### '+kind+'\n\n'+items.map(v=>'- '+v).join('\n')).join('\n\n')).join('\n\n')+'\n'
};
for(const [name,value]of Object.entries(outputs)){const file=new URL(name,root);if(process.argv.includes('--check')){if(fs.readFileSync(file,'utf8').replaceAll('\r\n','\n')!==value.replaceAll('\r\n','\n'))throw Error(name+' 이력 생성물이 다릅니다.');}else fs.writeFileSync(file,value);}
